export const DraggableNode = ({ type, label, color = '#6366f1', Icon = null }) => {
  const onDragStart = (e) => {
    e.dataTransfer.setData('application/reactflow', JSON.stringify({ nodeType: type }));
    e.dataTransfer.effectAllowed = 'move';
  };

  return (
    <div
      draggable
      onDragStart={onDragStart}
      style={{
        cursor: 'grab',
        height: 36,
        padding: '0 12px',
        display: 'flex',
        alignItems: 'center',
        gap: 6,
        borderRadius: 7,
        background: '#1a1a24',
        border: `1px solid #2a2a3a`,
        color: '#8888a8',
        fontSize: 12,
        fontWeight: 500,
        fontFamily: "'Inter', system-ui, sans-serif",
        flexShrink: 0,
        transition: 'background 0.15s, border-color 0.15s, color 0.15s',
        userSelect: 'none',
        WebkitUserDrag: 'element',
      }}
      onMouseEnter={e => {
        e.currentTarget.style.background = '#22222f';
        e.currentTarget.style.borderColor = `${color}66`;
        e.currentTarget.style.color = '#e8e8f0';
      }}
      onMouseLeave={e => {
        e.currentTarget.style.background = '#1a1a24';
        e.currentTarget.style.borderColor = '#2a2a3a';
        e.currentTarget.style.color = '#8888a8';
      }}
      onMouseDown={e => e.currentTarget.style.cursor = 'grabbing'}
      onMouseUp={e => e.currentTarget.style.cursor = 'grab'}
    >
      {Icon && (
        <span style={{ color, display: 'flex', alignItems: 'center' }}>
          <Icon size={13} strokeWidth={2.2} />
        </span>
      )}
      {label}
    </div>
  );
};
